// Orders v2 + Payments v2 (captures, refunds) through PayPal's official Server SDK (@paypal/paypal-server-sdk,
// generated by APIMatic). Approve-then-capture, no vaulting (forum reports of vaulting errors).
// Disputes stay on hand-written REST in disputes.ts: the SDK has no Disputes controller.
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
  type ApiResponse,
} from "@paypal/paypal-server-sdk";
import { z } from "zod";
import { paypalEnv } from "../../env";
import { fromCents, parseOk, PayPalError, toCents, type PpResponse } from "./client";

let sdk: { orders: OrdersController; payments: PaymentsController } | undefined;
function paypal() {
  if (sdk) return sdk;
  const e = paypalEnv(); // trimmed credentials; never logged (the SDK's default logger is a NullLogger)
  const client = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId: e.PAYPAL_CLIENT_ID, oAuthClientSecret: e.PAYPAL_CLIENT_SECRET },
    environment: e.PAYPAL_BASE_URL.includes("sandbox") ? Environment.Sandbox : Environment.Production,
    timeout: 0, // per-call timeouts come from an AbortSignal (refunds), as before
    // Never retry inside the SDK: a retried refund must go through the executor's reconcile step.
    httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } },
  });
  return (sdk = { orders: new OrdersController(client), payments: new PaymentsController(client) });
}

const debugId = (h: Record<string, string>) => Object.entries(h).find(([k]) => k.toLowerCase() === "paypal-debug-id")?.[1] ?? null;
const json = (b: unknown) => { try { return typeof b === "string" && b ? JSON.parse(b) : null; } catch { return b; } };

/**
 * Runs one SDK call and returns the raw response in our PpResponse shape, so the same tolerant Zod schemas parse
 * it. An SDK ApiError (any non-2xx) becomes a PayPalError, which the executor uses to tell a definite 4xx refusal
 * from an unknown outcome. Timeouts and network errors pass through unchanged (unknown outcome -> reconcile).
 */
export async function call(what: string, fn: () => Promise<ApiResponse<unknown>>): Promise<PpResponse> {
  try {
    const r = await fn();
    return { status: r.statusCode, ok: true, debugId: debugId(r.headers), body: json(r.body) };
  } catch (err) {
    if (err instanceof ApiError) throw new PayPalError({ status: err.statusCode, ok: false, debugId: debugId(err.headers), body: json(err.body) }, what);
    throw err;
  }
}

const Link = z.looseObject({ rel: z.string(), href: z.string() });
const Money = z.looseObject({ currency_code: z.string(), value: z.string() });

export const Order = z.looseObject({
  id: z.string(),
  status: z.string(), // CREATED | APPROVED | COMPLETED | ...
  links: z.array(Link).default([]),
  purchase_units: z.array(z.looseObject({
    payments: z.looseObject({ captures: z.array(z.looseObject({ id: z.string(), status: z.string(), amount: Money.optional() })).optional() }).optional(),
    shipping: z.looseObject({ address: z.looseObject({}).optional() }).optional(),
  })).default([]),
});
export type Order = z.infer<typeof Order>;

export async function createOrder(o: { amountCents: number; currency: string; description: string; returnUrl: string; cancelUrl: string; requestId: string }): Promise<{ order: Order; approveUrl: string }> {
  const res = await call("create order", () => paypal().orders.createOrder({
    paypalRequestId: o.requestId,
    body: {
      intent: CheckoutPaymentIntent.Capture,
      purchaseUnits: [{ amount: { currencyCode: o.currency, value: fromCents(o.amountCents) }, description: o.description.slice(0, 127) }],
      paymentSource: {
        paypal: {
          experienceContext: {
            userAction: PaypalExperienceUserAction.PayNow,
            shippingPreference: PaypalWalletContextShippingPreference.GetFromFile, // buyer's PayPal address -> order shipping (rubric R2)
            returnUrl: o.returnUrl,
            cancelUrl: o.cancelUrl,
          },
        },
      },
    },
  }));
  const order = parseOk(res, Order, "create order");
  // With payment_source.paypal the approval link is "payer-action"; older flows call it "approve".
  const approveUrl = order.links.find((l) => l.rel === "payer-action" || l.rel === "approve")?.href;
  if (!approveUrl) throw new Error(`create order: no approval link (debug_id ${res.debugId})`);
  return { order, approveUrl };
}

export async function getOrder(id: string): Promise<Order> {
  return parseOk(await call(`get order ${id}`, () => paypal().orders.getOrder({ id })), Order, `get order ${id}`);
}

/** Capture an APPROVED order. Same requestId -> PayPal returns the original capture instead of charging twice. */
export async function captureOrder(id: string, requestId: string): Promise<{ order: Order; captureId: string; status: string }> {
  const res = await call(`capture order ${id}`, () => paypal().orders.captureOrder({ id, paypalRequestId: requestId }));
  const order = parseOk(res, Order, `capture order ${id}`);
  const cap = order.purchase_units[0]?.payments?.captures?.[0];
  if (!cap) throw new Error(`capture order ${id}: no capture in response (debug_id ${res.debugId})`);
  return { order, captureId: cap.id, status: cap.status };
}

export const Capture = z.looseObject({ id: z.string(), status: z.string(), amount: Money });

/** Capture amount for the firewall snapshot (I1, I5). Refund totals come from our intents (S3). */
export async function getCapture(id: string): Promise<{ id: string; status: string; amountCents: number; currency: string }> {
  const c = parseOk(await call(`get capture ${id}`, () => paypal().payments.getCapturedPayment({ captureId: id })), Capture, `get capture ${id}`);
  return { id: c.id, status: c.status, amountCents: toCents(c.amount.value), currency: c.amount.currency_code };
}

export const Refund = z.looseObject({ id: z.string(), status: z.string() });

/**
 * Refund (part of) a capture. Reconcile strategy for refunds is the idempotency key: v2 has no "list refunds of a
 * capture" call, so a retry re-sends with the SAME PayPal-Request-Id and PayPal returns the original refund
 * (the SDK docs say refund keys are stored for 45 days). That PayPal honours the header on refunds is documented
 * but UNVERIFIED in our sandbox (needs a capture first). A 409 means "a previous call is in progress": not a
 * definite refusal in spirit, but it is a 4xx, so the executor marks it FAILED for a human to look at.
 */
export async function refundCapture(o: { captureId: string; amountCents: number; currency: string; ref: string; requestId: string; timeoutMs?: number }) {
  const res = await call(`refund capture ${o.captureId}`, () => paypal().payments.refundCapturedPayment({
    captureId: o.captureId,
    paypalRequestId: o.requestId,
    body: { amount: { currencyCode: o.currency, value: fromCents(o.amountCents) }, noteToPayer: `Refund from the seller [ref ${o.ref}]` },
  }, o.timeoutMs ? { abortSignal: AbortSignal.timeout(o.timeoutMs) } : undefined)); // a timeout = unknown outcome; the executor reconciles
  return parseOk(res, Refund, `refund capture ${o.captureId}`);
}
